using System.Text.Json;
using Bunit;
using Habitica.Application.Workspace;
using Habitica.Domain.Workspace;
using Habitica.WebApp.Components;
using Habitica.WebApp.State;
using Microsoft.Extensions.DependencyInjection;
using MudBlazor.Services;
namespace Habitica.WebApp.Tests.Workspace;
public sealed class ProjectHistoryPanelTests:BunitContext
{
    private static WorkspaceJournalSnapshot Source(string kind="completion")
    {
        using var data=JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"fixtures","project-retained-history-v1.json")));var row=data.RootElement.GetProperty("sections").EnumerateArray().Single(s=>s.GetProperty("kind").GetString()==kind);return new(WorkspaceJson.Deserialize(row.GetProperty("document").GetRawText()),30,WorkspaceTaskApiJson.Deserialize<WorkspaceCommandEntry[]>(row.GetProperty("commands").GetRawText()),[]);
    }
    private async Task<TodoOrganizationFixture> Setup(WorkspaceJournalSnapshot state)
    {
        JSInterop.Mode=JSRuntimeMode.Loose;Services.AddMudServices();var f=new TodoOrganizationFixture();Assert.Empty(WorkspaceRules.Validate(state.Document));f.Task.Client.State=state;f.Task.Client.Connected=true;await f.Task.Controller.LoadAsync(true);await f.Todo.RefreshSourcesAsync();await f.Todo.LoadSelectedAsync();Services.AddSingleton<IAppSessionController>(f.Task.Session);Services.AddSingleton<IWorkspaceCloudClient>(f.Task.Client);Services.AddSingleton(f.Task.Database);Services.AddSingleton(f.Task.Controller);Services.AddSingleton(f.Organization);Services.AddSingleton(f.Todo);Services.AddSingleton<TodoTaskDraftStore>();return f;
    }
    private static void Save(string name,string markup,string state,string route="/todo/history")=>Qualification.PageLayoutEvidence.Save(name,markup,route,state,["form","actions","confirmation","disabled-controls","error","navigation"],nameof(ProjectHistoryPanelTests));
    [Fact]public async Task Exact_current_projects_retained_archives_and_unassigned_keep_event_details_and_recovery_limits()
    {
        var source=Source();using var f=await Setup(source);var cut=Render<TodoHistoryPanel>();Assert.Equal(6,cut.FindAll("[data-testid^=history-row-]").Count);var a=source.Document.Projects[0];var b=source.Document.Projects[1];var archived=source.Document.Projects.Single(p=>p.IsArchived&&!p.IsRemoved);var removed=source.Document.Projects.Single(p=>p.IsRemoved);Assert.Contains(a.Id.ToString("D"),cut.Find("[data-testid=history-project]").TextContent);Assert.Contains(b.Id.ToString("D"),cut.Find("[data-testid=history-project]").TextContent);Save("project-history-all",cut.Markup,"all-current-project-identities-and-retained-events");
        cut.Find("[data-testid=history-project]").Change(b.Id.ToString("D"));Assert.Single(cut.FindAll("[data-testid^=history-row-]"));Assert.Contains("Original café",cut.Markup);Assert.Contains(b.Id.ToString("D"),cut.Find("[data-testid=history-current-placement]").TextContent);Assert.DoesNotContain(a.Id.ToString("D"),cut.Find("[data-testid=history-current-placement]").TextContent);Assert.Contains("does not establish event-time membership",cut.Markup);Save("project-history-current",cut.Markup,"current-reassignment-with-original-accepted-title");
        cut.Find("[data-testid=history-project]").Change(archived.Id.ToString("D"));Assert.Contains("Task archived: Yes",cut.Markup);Assert.Contains("Event archived: Yes",cut.Markup);Assert.Empty(cut.FindAll("[data-testid^=history-restore-]"));Save("project-history-archived",cut.Markup,"archived-project-and-completed-archive-without-unsafe-restore");
        cut.Find("[data-testid=history-project]").Change("unassigned");Assert.Equal(2,cut.FindAll("[data-testid^=history-row-]").Count);Assert.Contains("retained removed project",cut.Markup);Assert.Contains("Unassigned; no retained project",cut.Markup);Save("project-history-unassigned",cut.Markup,"removed-project-placement-distinguished-from-null");cut.Find("[data-testid=history-project]").Change(removed.Id.ToString("D"));Assert.Single(cut.FindAll("[data-testid^=history-row-]"));Assert.Contains(removed.Id.ToString("D"),cut.Find("[data-testid=history-current-placement]").TextContent);cut.Find("[data-testid=history-query]").Change("No matching event");Assert.Empty(cut.FindAll("[data-testid^=history-row-]"));Assert.NotNull(cut.Find("[data-testid=history-empty]"));Save("project-history-empty",cut.Markup,"project-text-AND-empty-result");Assert.Empty(f.Task.Client.PreparationIds);
    }
    [Fact]public async Task Habit_project_text_direction_and_dates_combine_without_rewriting_old_scores()
    {
        var source=Source("habit");using var f=await Setup(source);var cut=Render<TodoHistoryPanel>();cut.Find("[data-testid=history-activity]").Change("Habit");cut.Find("[data-testid=history-project]").Change(source.Document.Projects[1].Id.ToString("D"));Assert.Equal(5,cut.FindAll("[data-testid^=history-row-]").Count);cut.Find("[data-testid=history-direction]").Change("Down");Assert.Single(cut.FindAll("[data-testid^=history-row-]"));Assert.Contains("No old note",cut.Markup);cut.Find("[data-testid=history-from]").Change("2026-10-17");cut.Find("[data-testid=history-through]").Change("2026-10-17");cut.Find("[data-testid=history-query]").Change("No old");Assert.Single(cut.FindAll("[data-testid^=history-row-]"));Save("project-history-habit",cut.Markup,"project-text-direction-UTC-intersection");Assert.Equal(9,f.Task.Client.State.Document.HabitScores.Count);Assert.Empty(f.Task.Client.PreparationIds);
    }
    [Fact]public async Task Scoped_route_and_projects_links_bind_exact_source_and_reject_mismatched_or_malformed_context()
    {
        var source=Source();using var f=await Setup(source);var project=source.Document.Projects[1];var projects=Render<TodoOrganizationPanel>();var link=projects.Find($"[data-testid=project-history-{project.Id:D}]").GetAttribute("href")!;Assert.Contains("projectId="+project.Id.ToString("D"),link);Assert.Contains("workspaceId="+source.Document.Id.ToString("D"),link);Assert.Contains("source=cloud",link);Save("project-history-projects",projects.Markup,"scoped-project-history-navigation","/todo/projects");
        var cut=Render<TodoHistoryPanel>(p=>p.Add(x=>x.ProjectReference,project.Id.ToString("D")).Add(x=>x.WorkspaceReference,source.Document.Id.ToString("D")).Add(x=>x.SourceReference,"cloud"));Assert.Single(cut.FindAll("[data-testid^=history-row-]"));cut.Render(p=>p.Add(x=>x.WorkspaceReference,Guid.NewGuid().ToString("D")));Assert.NotNull(cut.Find("[data-testid=history-error]"));Assert.Empty(cut.FindAll("[data-testid^=history-row-]"));Save("project-history-scope",cut.Markup,"mismatched-source-no-event-fallback");cut.Render(p=>p.Add(x=>x.ProjectReference,"not-a-project"));Assert.NotNull(cut.Find("[data-testid=history-error]"));Assert.Empty(cut.FindAll("[data-testid^=history-row-]"));Assert.Empty(f.Task.Client.PreparationIds);
    }
    [Fact]public async Task Filtered_original_restore_recovers_one_receipt_after_lost_acknowledgement_and_account_change_hides_private_rows()
    {
        var source=Source();using var f=await Setup(source);Assert.True(WorkspaceJournalValidation.IsValid(source));var cut=Render<TodoHistoryPanel>(p=>p.Add(x=>x.ProjectReference,source.Document.Projects[1].Id.ToString("D")));var row=source.Document.Completions.Single(e=>e.TaskId==Guid.Parse("60000000-0000-4000-8000-000000000105"));cut.Find($"[data-testid=history-restore-{row.Id:D}]").Click();cut.WaitForAssertion(()=>Assert.NotNull(f.Task.Controller.Preview));var command=f.Task.Controller.Preview!.PreparedCommandId;Assert.False(f.Task.Controller.Preview.MayAffectHabitica);f.Task.Client.LoseAcceptance=true;cut.Find("[data-testid=todo-confirm]").Click();cut.WaitForAssertion(()=>Assert.True(f.Task.Controller.AcceptanceUnknown));Save("project-history-restore-unknown",cut.Markup,"original-restore-receipt-required-with-project-context");await f.Todo.CheckOriginalAsync();Assert.Equal(command,f.Task.Controller.LastReceipt!.CommandId);Assert.Single(f.Task.Client.AcceptedIds);Assert.Single(f.Task.Client.State.Document.Restorations!);Assert.Single(cut.FindAll("[data-testid^=history-row-]"));Assert.Contains("Restored UTC",cut.Markup);f.Task.Session.SetState(f.Task.Session.State with{UserId=Guid.NewGuid().ToString("D")});cut.WaitForAssertion(()=>Assert.Empty(cut.FindAll("[data-testid^=history-row-]")));Assert.DoesNotContain("Original café",cut.Markup);Save("project-history-account",cut.Markup,"account-change-clears-private-event-rows");
    }
}
